package com.servoc.app.ui;

import android.content.Context;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.Spinner;
import android.widget.ArrayAdapter;
import android.widget.AdapterView;
import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.RectF;
import android.widget.ImageView;
import android.widget.TextView;
import com.servoc.app.data.ExperimentQueries;
import com.servoc.app.data.SessionSeries;
import com.servoc.app.report.AnalyticalCharts;
import com.servoc.app.chemcore.ChemCoreAnalysisPresenter;
import com.servoc.app.chemcore.ChemCoreDecisionRepository;
import org.json.JSONObject;
import org.json.JSONArray;
import java.util.List;
import java.util.Locale;

/** User-facing saved measurement history. Developer approval/reference-bank controls are intentionally absent. */
public final class ReportsTab {
    private final HazRobHost host;private final ScrollView scroll;private final LinearLayout list;private final TextView summary,details,kpis,screening,safety,candidates,quality;private final Button pdf,xlsx;private final Spinner chartSelector;private final ImageView chartView;private final ChemCoreDecisionRepository decisions;private long selectedId=-1;
    public ReportsTab(Context c,HazRobHost host){this.host=host;scroll=new ScrollView(c);scroll.setFillViewport(true);LinearLayout root=UiKit.vbox(c);root.setPadding(UiKit.dp(c,8),UiKit.dp(c,6),UiKit.dp(c,8),UiKit.dp(c,12));root.setBackgroundColor(0xFF0E1116);scroll.addView(root);root.addView(UiKit.title(c,"السجل والتقارير"),UiKit.full(c));summary=UiKit.text(c,"لا توجد قياسات محفوظة");summary.setBackgroundColor(0xFF151A20);root.addView(summary,UiKit.full(c));kpis=UiKit.text(c,"مؤشرات التقرير: —");kpis.setBackgroundColor(0xFF151A20);root.addView(kpis,UiKit.full(c));screening=UiKit.text(c,"فحص 144: —");screening.setBackgroundColor(0xFF11171D);root.addView(screening,UiKit.full(c));safety=UiKit.text(c,"التعرض والاشتعال: —");safety.setBackgroundColor(0xFF11171D);root.addView(safety,UiKit.full(c));quality=UiKit.text(c,"جودة القياس: —");quality.setBackgroundColor(0xFF151A20);root.addView(quality,UiKit.full(c));candidates=UiKit.text(c,"المرشحون: —");candidates.setBackgroundColor(0xFF11171D);candidates.setTextIsSelectable(true);root.addView(candidates,UiKit.full(c));details=UiKit.text(c,"اختر قياسًا محفوظًا لعرض ملخصه أو تصديره.");details.setBackgroundColor(0xFF11171D);details.setTextIsSelectable(true);root.addView(details,UiKit.full(c));LinearLayout actions=UiKit.hbox(c);pdf=UiKit.button(c,"تصدير PDF");pdf.setOnClickListener(v->export("pdf"));actions.addView(pdf,UiKit.weight(1));xlsx=UiKit.button(c,"تصدير Excel");xlsx.setOnClickListener(v->export("xlsx"));actions.addView(xlsx,UiKit.weight(1));root.addView(actions,UiKit.full(c));chartSelector=new Spinner(c);String[] chartNames={"استجابة MQ / Rs-R0","البصمة الكيميائية","المرشحون","بواقي المرشحين Residual","فحص 144","توزيع مستويات الدليل M0-M4","التعرض والاشتعال","الحرارة","الرطوبة","الضغط","الصوت"};chartSelector.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,chartNames));root.addView(chartSelector,UiKit.full(c));chartView=new ImageView(c);chartView.setAdjustViewBounds(true);chartView.setMinimumHeight(UiKit.dp(c,240));chartView.setBackgroundColor(Color.WHITE);root.addView(chartView,UiKit.full(c));chartSelector.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){renderSelectedChart(pos);}public void onNothingSelected(AdapterView<?> p){}});list=UiKit.vbox(c);root.addView(list,UiKit.full(c));decisions=new ChemCoreDecisionRepository(host.database());setEnabled(false);}
    public View view(){return scroll;}
    public void refresh(){list.removeAllViews();List<ExperimentQueries.Record> rows=ExperimentQueries.recent(host.database(),100);summary.setText("القياسات المحفوظة: "+host.database().count()+" • المعروض: "+rows.size());if(rows.isEmpty()){selectedId=-1;setEnabled(false);list.addView(UiKit.small(list.getContext(),"احفظ نتيجة مكتملة من تبويب القياس والتحليل."),UiKit.full(list.getContext()));details.setText("لا توجد قياسات محفوظة.");return;}if(selectedId<0)selectedId=rows.get(0).id;boolean found=false;for(ExperimentQueries.Record r:rows){if(r.id==selectedId)found=true;Button b=UiKit.button(list.getContext(),"#"+r.id+"   "+safe(r.ts)+"   "+safe(r.protocol));b.setOnClickListener(v->select(r.id));list.addView(b,UiKit.full(list.getContext()));}if(!found)selectedId=rows.get(0).id;showSelected();}
    private void select(long id){selectedId=id;showSelected();}
    private void showSelected(){ExperimentQueries.Record r=ExperimentQueries.byId(host.database(),selectedId);if(r==null){setEnabled(false);return;}setEnabled(true);JSONObject d=json(r.payload),m=d.optJSONObject("measurement"),e=d.optJSONObject("env"),relay=d.optJSONObject("relay"),a=json(r.analytics);int results=a.optJSONArray("results")==null?0:a.optJSONArray("results").length();boolean mqOn=relay!=null&&relay.optBoolean("on",relay.optInt("mask",0)!=0);long powerMs=relay==null?0:relay.optLong("power_ms",0);StringBuilder s=new StringBuilder("القياس #").append(r.id).append("\nSession: ").append(r.sessionId==null||r.sessionId.isEmpty()?"—":r.sessionId).append("\nUTC: ").append(safe(r.ts)).append("\nالنوع: ").append(safe(r.protocol)).append("\nMQ Power: ").append(mqOn?"ON":"OFF").append(" • GPIO25 • 8 sensors");if(mqOn)s.append(" • ").append(powerMs).append(" ms");if(m!=null)s.append("\nدورة MQ: ").append(m.optString("state","—"));if(e!=null&&e.optBoolean("ok",false)){s.append("\nالحرارة: ").append(fmt(e.optDouble("temperature",Double.NaN))).append(" °C");double h=e.optDouble("humidity",Double.NaN);if(Double.isFinite(h))s.append(" • الرطوبة: ").append(fmt(h)).append(" %RH");s.append(" • الضغط: ").append(fmt(e.optDouble("pressure",Double.NaN))).append(" hPa");}s.append("\nنتائج الأدلة الكيميائية المسجلة: ").append(results);String chemcoreSession=r.sessionId==null?"":r.sessionId.trim();JSONObject cr=chemcoreSession.isEmpty()?null:decisions.latestPayloadForSession(chemcoreSession);if(cr!=null){String outcome=cr.optString("outcome","—"),tier=cr.optString("evidence_tier","—");double ppm=cr.optDouble("ppm",Double.NaN);JSONObject mq=cr.optJSONObject("measurement_quality");kpis.setText("القرار: "+outcome+" • الدليل: "+tier+" • PPM: "+(Double.isFinite(ppm)?fmt(ppm):"محجوب")+" • جودة القياس: "+(mq==null?"—":mq.optString("state",mq.optString("overall_state","—"))));quality.setText(qualitySummary(mq));candidates.setText(candidateSummary(cr));s.append("\n\n=== نتيجة ChemCore المعتمدة ===\n").append(ChemCoreAnalysisPresenter.summary(cr));JSONObject sc=cr.optJSONObject("screening_144");if(sc!=null){screening.setText("فحص 144 مادة: "+sc.optString("state","—")+" • "+sc.optInt("evaluated_count",0)+"/"+sc.optInt("target_count",144));s.append("\nفحص 144: ").append(sc.optString("state","—")).append(" • ").append(sc.optInt("evaluated_count",0)).append("/").append(sc.optInt("target_count",144));}else screening.setText("فحص 144: —");JSONObject gx=cr.optJSONObject("gas_exposure_ppm");if(gx!=null){safety.setText("التعرض: "+gx.optString("toxicity_state",gx.optString("state","—"))+" • الاشتعال: "+gx.optString("flammability_state","—")+" • نسبة أولوية الخطر: "+fmt(gx.optDouble("hazard_priority_ratio",Double.NaN)));s.append("\nالتعرض: ").append(gx.optString("toxicity_state",gx.optString("state","—"))).append(" • الاشتعال: ").append(gx.optString("flammability_state","—"));}else safety.setText("التعرض والاشتعال: محجوب/غير متاح");}else{kpis.setText("ChemCore: —");screening.setText("فحص 144: —");safety.setText("التعرض والاشتعال: —");quality.setText("جودة القياس: —");candidates.setText("المرشحون: —");s.append("\n\nChemCore: لا توجد نتيجة تحليل مرتبطة بهذه الجلسة.");}details.setText(s.toString());renderSelectedChart(chartSelector.getSelectedItemPosition());}
    private void renderSelectedChart(int pos){ExperimentQueries.Record r=ExperimentQueries.byId(host.database(),selectedId);if(r==null){chartView.setImageDrawable(null);return;}SessionSeries.Series ss=SessionSeries.forExperiment(host.database(),r);String sid=r.sessionId==null?"":r.sessionId.trim();JSONObject cc=sid.isEmpty()?null:decisions.latestPayloadForSession(sid);Bitmap b=Bitmap.createBitmap(1200,650,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(Color.WHITE);RectF box=new RectF(12,12,1188,638);switch(pos){case 0:AnalyticalCharts.mqRsR0(canvas,box,ss);break;case 1:AnalyticalCharts.fingerprint(canvas,box,ss);break;case 2:AnalyticalCharts.candidates(canvas,box,cc);break;case 3:AnalyticalCharts.candidateResiduals(canvas,box,cc);break;case 4:AnalyticalCharts.screening144(canvas,box,cc);break;case 5:AnalyticalCharts.evidenceTiers(canvas,box,cc);break;case 6:AnalyticalCharts.exposureRatios(canvas,box,cc);break;case 7:AnalyticalCharts.temperature(canvas,box,ss);break;case 8:AnalyticalCharts.humidity(canvas,box,ss);break;case 9:AnalyticalCharts.pressure(canvas,box,ss);break;case 10:AnalyticalCharts.sound(canvas,box,ss);break;default:AnalyticalCharts.candidates(canvas,box,cc);}chartView.setImageBitmap(b);}
    private static String qualitySummary(JSONObject q){if(q==null)return "جودة القياس: —";StringBuilder s=new StringBuilder("جودة القياس: ").append(q.optString("state",q.optString("overall_state","—")));JSONArray gates=q.optJSONArray("gates");if(gates!=null)s.append(" • البوابات: ").append(gates.length());int valid=q.optInt("valid_mq_channels",q.optInt("valid_channels",-1));if(valid>=0)s.append(" • MQ صالح: ").append(valid).append("/8");return s.toString();}
    private static String candidateSummary(JSONObject p){JSONArray a=p==null?null:p.optJSONArray("candidates");if(a==null||a.length()==0)return "المرشحون: لا توجد فرضيات قابلة للحل";StringBuilder s=new StringBuilder("المرشحون الديناميكيون: ").append(a.length());int n=Math.min(8,a.length());for(int i=0;i<n;i++){JSONObject q=a.optJSONObject(i);if(q==null)continue;double post=q.optDouble("posterior",Double.NaN);s.append("\n#").append(i+1).append(" ").append(q.optString("label","—")).append(" • ").append(Double.isFinite(post)?String.format(Locale.US,"%.1f%%",100*post):"—").append(" • ").append(q.optString("evidence_tier","—")).append(" • residual ").append(fmt(q.optDouble("residual_rms",Double.NaN)));}if(a.length()>n)s.append("\n… +").append(a.length()-n).append(" مرشح؛ القائمة الكاملة في نتائج التحليل");return s.toString();}
    private void setEnabled(boolean v){pdf.setEnabled(v);xlsx.setEnabled(v);}private void export(String f){if(selectedId<0){host.showToast("اختر قياسًا أولًا");return;}host.requestExport(f,selectedId);}private static JSONObject json(String s){try{return s==null?new JSONObject():new JSONObject(s);}catch(Exception e){return new JSONObject();}}private static String safe(String s){return s==null?"":s;}private static String fmt(double v){return Double.isFinite(v)?String.format(Locale.US,"%.2f",v):"—";}
}
